<?php
declare(strict_types=1);
$brandName=is_string($brandName ?? null)?$brandName:'Talyvane';
$items=is_array($items ?? null)?$items:[];
$csrf=is_string($csrf ?? null)?$csrf:'';
$error=is_string($error ?? null)?$error:'';
$notice=is_string($notice ?? null)?$notice:'';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Profile media review · <?= $escape($brandName) ?></title>
<style>
:root{color-scheme:light;--ink:#182638;--muted:#667487;--paper:#f4f2ed;--panel:#fffefa;--line:#e6e2d9;--night:#142235;--danger:#8b3535}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 Inter,ui-sans-serif,system-ui,sans-serif}.shell{width:min(1100px,calc(100% - 32px));margin:auto}.top{padding:22px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.brand{font:600 20px Georgia,serif;letter-spacing:.08em}main{padding:42px 0 80px}h1{font:400 clamp(34px,5vw,52px)/1.1 Georgia,serif;margin:0 0 10px}.muted{color:var(--muted)}.panel{background:var(--panel);border:1px solid var(--line);padding:22px;margin:22px 0;display:grid;grid-template-columns:220px 1fr;gap:24px}.preview{width:100%;aspect-ratio:4/5;object-fit:contain;background:#e9e6df}.field{display:grid;gap:7px;margin:14px 0}.field label{font-size:12px;font-weight:700}.check{display:flex;gap:9px;align-items:flex-start;margin:12px 0;font-size:13px}.check input{margin-top:4px}.field select,.field textarea{width:100%;padding:11px;border:1px solid var(--line);background:white;font:inherit}.button{border:0;background:var(--night);color:white;padding:12px 18px;font-weight:700;cursor:pointer}.notice,.error{padding:12px 14px;margin:16px 0}.notice{background:#edf4eb;border:1px solid #d5e3d0}.error{background:#fff3f1;border:1px solid #e7c9c3;color:var(--danger)}@media(max-width:680px){.panel{grid-template-columns:1fr}.preview{max-width:260px}}
