<?php foreach ($items as $item): ?><section class="panel"><div><img class="preview" src="/admin/profile-media/<?= $escape($item['id']) ?>/preview" alt="Pending profile image preview" loading="lazy"></div><div><h2><?= $escape($item['profile_name']) ?></h2><p class="muted"><?= $escape($item['destination_name']) ?> · <?= $escape($item['width']) ?> × <?= $escape($item['height']) ?> px · <?= $escape($item['created_at']) ?></p><p><a href="/profiles/<?= $escape($item['profile_slug']) ?>">Open public profile</a></p>
<form method="post" action="/admin/profile-media/<?= $escape($item['id']) ?>/review"><input type="hidden" name="_csrf" value="<?= $escape($csrf) ?>"><div class="field"><label for="decision-<?= $escape($item['id']) ?>">Decision</label><select id="decision-<?= $escape($item['id']) ?>" name="decision" required><option value="">Choose decision</option><option value="approved">Approve</option><option value="rejected">Reject and delete image</option></select></div>
<div class="field"><label for="scope-<?= $escape($item['id']) ?>">Approved audience</label><select id="scope-<?= $escape($item['id']) ?>" name="media_scope" required><option value="public">Public profile</option><option value="members_only">Members-only (separate current companion opt-in and active entitlement required)</option></select></div>
<label class="check"><input type="checkbox" name="adult_safety_confirmed" value="1"><span>I confirm every identifiable person depicted is an adult aged 18 or older and no minor is depicted.</span></label>
<label class="check"><input type="checkbox" name="rights_confirmed" value="1"><span>I reviewed the uploader's image-rights attestation and available evidence; no apparent rights conflict exists.</span></label>
<label class="check"><input type="checkbox" name="consent_confirmed" value="1"><span>I reviewed the image and available evidence; no apparent coercion or non-consensual depiction exists.</span></label>
<div class="field"><label for="reason-<?= $escape($item['id']) ?>">Review reason (10–500 characters)</label><textarea id="reason-<?= $escape($item['id']) ?>" name="reason" rows="3" minlength="10" maxlength="500" required></textarea></div><button class="button" type="submit">Record human review</button></form></div></section><?php endforeach; ?>
</main></body></html>
